import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv, vec2, vec3, mix, smoothstep, uniform, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DoubleSide, Color } = ctx.THREE;

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const inkCol = new Color(colors.ink);
  const paperCol = new Color(colors.paper);
  const accentCol = new Color(colors.accent);
  const surfCol = new Color(colors.surface);

  const group = new Group();
  group.name = 'hub-pricing-card-2-label';

  const timelines = [];
  const geometries = [];
  const materials = [];

  // Atlas region 0,0,512,320 -> aspect 1.6
  const planeW = 1.6;
  const planeH = planeW / (512 / 320); // 1.0

  // --- Engineered gradient backdrop plane (label surface) ---
  const backdropGeo = new PlaneGeometry(planeW * 1.18, planeH * 1.18);
  geometries.push(backdropGeo);

  const inkRGB = vec3(float(inkCol.r), float(inkCol.g), float(inkCol.b));
  const surfRGB = vec3(float(surfCol.r), float(surfCol.g), float(surfCol.b));
  const accentRGB = vec3(float(accentCol.r), float(accentCol.g), float(accentCol.b));
  const paperRGB = vec3(float(paperCol.r), float(paperCol.g), float(paperCol.b));

  const vGrad = float(1.0).sub(uv().y); // 1 at bottom, 0 at top
  const baseGrad = mix(surfRGB, inkRGB, smoothstep(float(0.0), float(1.0), uv().y));
  // Thin engineered accent edge at the bottom rail (<=10% of frame)
  const accentEdge = smoothstep(float(0.12), float(0.0), vGrad).mul(float(0.55));
  const backdropCol = mix(baseGrad, accentRGB, accentEdge);

  const backdropMat = new MeshBasicNodeMaterial({
    colorNode: backdropCol,
    transparent: true,
    opacity: 1.0,
    side: DoubleSide,
    toneMapped: true,
  });
  materials.push(backdropMat);

  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -0.02;
  group.add(backdrop);

  // --- Grain-textured surface from the ceramic-grain map (atlas region 0,0,512,320) ---
  const grainGeo = new PlaneGeometry(planeW, planeH);
  geometries.push(grainGeo);
  const grainTexUniform = uniform(null);

  const grainMat = new MeshBasicNodeMaterial({
    transparent: true,
    side: DoubleSide,
    toneMapped: true,
  });
  materials.push(grainMat);

  // Use the grain map's red channel to modulate the engineered surface brightness
  const g = texture(grainTexUniform, uv());
  // paper-tinted grain brushing on the dark surface, very subtle
  const grainCol = mix(inkRGB, paperRGB.mul(float(0.18)), g.r.mul(float(0.22)));
  grainMat.colorNode = grainCol;
  grainMat.opacityNode = float(0.85);

  const grainMesh = new Mesh(grainGeo, grainMat);
  grainMesh.position.z = 0.0;
  group.add(grainMesh);

  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        tex.wrapS = ctx.THREE.RepeatWrapping;
        tex.wrapT = ctx.THREE.RepeatWrapping;
        tex.colorSpace = ctx.THREE.SRGBColorSpace;
        grainTexUniform.value = tex;
        grainMat.needsUpdate = true;
      })
      .catch(() => {});
  }

  // --- Text content via fontAtlas (Lora 400 display feel, paper color) ---
  for (const item of items) {
    const fs = item.typography?.fontSize ?? 39;
    const labelStr = String(item.text ?? item.label ?? '');
    const txtObj = ctx.fontAtlas.createText(labelStr, {
      fontSize: fs,
      color: colors.paper,
      align: 'center',
      letterSpacingPx: 1.5,
    });
    txtObj.position.set(0, 0, 0.025);
    group.add(txtObj);
  }

  // --- Weighted-settle entrance (no primitive requested) ---
  group.scale.set(0.96, 0.96, 0.96);
  const tl = gsap.timeline();
  timelines.push(tl);
  tl.fromTo(
    group.position,
    { y: group.position.y + 0.18 },
    { y: group.position.y, duration: 0.7, ease: 'power3.out' },
    0
  );
  tl.to(
    group.scale,
    { x: 1.02, y: 1.02, z: 1.0, duration: 0.55, ease: 'power2.out' },
    0
  );
  tl.to(
    group.scale,
    { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'power4.out' },
    0.55
  );

  // No handlers (static composition, no interactivity)
  group.userData.handlers = {
    onClick: null,
    onHover: null,
    onPointerMove: null,
  };

  group.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    geometries.forEach((g) => g.dispose());
    materials.forEach((m) => m.dispose());
    const tex = grainTexUniform.value;
    if (tex && tex.dispose) tex.dispose();
  };

  return group;
}
